from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
PAIR=ROOT/'knowledge-base/restart-2026/pairs'

d=PAIR/'d4rt'
body=(d/'prompt.v1.txt').read_text(encoding='utf-8')
body=body.replace('The attached Neuralangelo image is a visual reference','The historical Neuralangelo image was a visual reference')
body=body.replace('This rail supports three short incoming context arrows to the decoder\'s independent query lanes.','The same context enters the shared decoder through one TOP context port, separated from all query ports.')
body=body.replace('Draw one branch from the F output into a slim vertical feature rail adjacent to the decoder.','Draw one short connection from F into the TOP port of the shared decoder, with the small label F at that port.')
body=body.replace('The incoming F rail enters from above or the inner side of every slot.','One F context port enters the decoder at its top; internal context reuse is indicated by the block label, not separate wires through query tokens.')
body=body.replace('The sum produces one query token, which then routes upward to the decoder.','The sum produces one query token. Match this token to the decoder through the repeated symbol q, with NO long connecting line between the two regions.')
body=body.replace('Route a narrow solid arrow from the summed token to the decoder query-input side, with no connection into the F output as if the query altered the cached scene.','Use the repeated q notation to associate construction with decoder inputs. Draw no arrow out of this summed token; its derivation ends at the token.')
header='''LOCAL REPAIR OF THE ATTACHED D4RT SECOND DRAFT. Preserve the crane scenes, images, lower examples and all correct labels. Make the following exact changes before applying the full specification below. DELETE the complete blue return-shaped route from the bottom Query token around the construction region into the bottom of the F rail. DELETE the complete red q line rising into q_A. DELETE the vertical F rail beside the decoder and its three leftward-context stubs into q_A/q_B/q_C. Replace these routes with ONE short F-to-decoder connection entering the TOP center of Shared decoder D, carrying the small label F. Keep the three separate q_A/q_B/q_C inputs inside the decoder and their respective cross-attention-to-P outputs. The query construction ends at its q token and has NO outgoing line at all; its correspondence to the decoder is conveyed only by the repeated q symbol. Leave the source crop outside the five-term sum, with no plus sign after the raw crop. Keep the existing correct five embedding summands. In lower-right Camera geometry, preserve both clouds pointing into Umeyama, DELETE the right-cloud-to-Relative-pose arrow, and draw ONE clear arrow from the BOTTOM of Umeyama down a short distance then right to the Relative pose glyph. This output route must have visible uninterrupted contact with Umeyama's lower boundary. Do not add more arrows to make the layout dense. The attached D4RT image is the edit target.\n\n'''
(d/'prompt.txt').write_text(header+body,encoding='utf-8')

